import{_ as t,o as i,c as a,j as e,a as o,aa as s}from"./chunks/framework.BAs_AphD.js";const c="/buildary-help-preview/media/en/diary/en_menu_dne2.jpg",n="/buildary-help-preview/media/en/diary/en_kopirovani_od_subdodavatelu.jpg",d="/buildary-help-preview/media/en/diary/en_menu_dne3.jpg",l="/buildary-help-preview/media/en/diary/en_kopirovani_z_casti_staveb.jpg",p="/buildary-help-preview/media/en/diary/en_kopirovani_z_casti_staveb_vysledek.jpg",w=JSON.parse('{"title":"Copying Records from Subcontractor Diaries and Diaries of Project Sections","description":"","frontmatter":{"title":"Copying Records from Subcontractor Diaries and Diaries of Project Sections","wiki":"en:diary:copysubcontractors"},"headers":[],"relativePath":"en/diary/copysubcontractors.md","filePath":"en/diary/copysubcontractors.md","lastUpdated":1794388980000}'),h={name:"en/diary/copysubcontractors.md"};function y(f,r,u,m,b,g){return i(),a("div",null,[...r[0]||(r[0]=[e("h1",{id:"copying-records-from-subcontractor-diaries-and-diaries-of-project-sections",tabindex:"-1"},[o("Copying Records from Subcontractor Diaries and Diaries of Project Sections "),e("a",{class:"header-anchor",href:"#copying-records-from-subcontractor-diaries-and-diaries-of-project-sections","aria-label":'Permalink to "Copying Records from Subcontractor Diaries and Diaries of Project Sections"'},"​")],-1),e("h3",{id:"video-copying-records-from-subcontractor-diaries",tabindex:"-1"},[o("Video: Copying Records from Subcontractor Diaries "),e("a",{class:"header-anchor",href:"#video-copying-records-from-subcontractor-diaries","aria-label":'Permalink to "Video: Copying Records from Subcontractor Diaries"'},"​")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/IbyZ6Av8g7s",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),s('<p>You can save a significant amount of work by creating diaries for your subcontractors in the application and importing data from these diaries into your own diary.</p><h2 id="copying-records-from-subcontractor-diaries" tabindex="-1">Copying Records from Subcontractor Diaries <a class="header-anchor" href="#copying-records-from-subcontractor-diaries" aria-label="Permalink to &quot;Copying Records from Subcontractor Diaries&quot;">​</a></h2><figure class="shot" style="--w:400px;"><img src="'+c+'" alt="" width="400" loading="lazy"></figure><p>If you have significant subcontractors working on the project, we recommend creating subcontractor diaries for them within the project in the application. It is then very easy to transfer data from their diaries into your own diary, which you maintain for the investor.</p><p>In the day menu, select <strong>Copy from subcontractor diaries</strong>.</p><figure class="shot" style="--w:600px;"><img src="'+n+'" alt="" width="600" loading="lazy"></figure><p>The window displays all subcontractor diaries linked to the selected diary. This is therefore also the quickest way to check what your subcontractors have entered into their diaries today. It is considerably faster than opening each diary individually.</p><p>You can expand the diaries down to individual records and use the checkboxes to select individual records or higher-level groups to be copied. Attachments can also be copied.</p><p>The wording of the records can be edited at this stage to match the required format. This editing does not affect the original record in the subcontractor&#39;s diary.</p><p>Click <strong>Copy</strong> to transfer the selected records to the parent diary.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The application only offers diaries for copying if they contain data for the selected day. If a subcontractor diary contains no data for that day, it will not appear in the list at all.</p></div><h2 id="copying-records-from-diaries-of-project-sections-object-diaries-to-the-central-project-diary" tabindex="-1">Copying Records from Diaries of Project Sections (Object Diaries) to the Central Project Diary <a class="header-anchor" href="#copying-records-from-diaries-of-project-sections-object-diaries-to-the-central-project-diary" aria-label="Permalink to &quot;Copying Records from Diaries of Project Sections (Object Diaries) to the Central Project Diary&quot;">​</a></h2><figure class="shot" style="--w:400px;"><img src="'+d+'" alt="" width="400" loading="lazy"></figure><p>If the project is divided into individual structures or operational units and a separate object diary (<strong>Project Section Diary</strong>) is maintained for each one, data can be transferred from these diaries to the <strong>Central Project Diary</strong>. Only records from the <strong>Performed Works</strong> section can be transferred from object diaries.</p><img src="'+l+'" alt="" width="600" loading="lazy"><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The first record is always selected for transfer by default. We therefore recommend formulating the first record in an object diary in such a way that it can be transferred to the Central Project Diary semi-automatically.</p></div><figure class="shot" style="--w:600px;"><img src="'+p+'" alt="" width="600" loading="lazy"></figure><p>All records transferred from a single object diary are always inserted into one record in the Central Project Diary, headed with the number and name of the relevant object diary.</p>',18)])])}const j=t(h,[["render",y]]);export{w as __pageData,j as default};
